head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.setJSON(jsonData);
};
scwin.Dbclick = function(Id) {
    var el = WebSquare.wUnit.getDomById(Id);
    el.addEventListener('dblclick', function(e) {
        console.log(e);
    });
    var event = new MouseEvent('dblclick', {
        bubbles: true,
        cancelable: true,
        composed: true
    });
    el.dispatchEvent(event);
}
scwin.checkAttr = function() {
    return WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col1').style.display == 'block';
}
scwin.setVal = function() {
    WebSquare.wUnit.getObjById('gridView1').setCellReadOnly(0, 0, false);
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkAttr()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
